add_action( 'woocommerce_product_options_general_product_data', 'perfectpixel_product_fee_checkbox' );
add_action( 'woocommerce_admin_process_product_object', 'perfectpixel_product_fee_save' );
add_action( 'woocommerce_cart_calculate_fees', 'perfectpixel_product_fee_apply' );

function perfectpixel_product_fee_checkbox() {
	echo '<div class="options_group">';
	woocommerce_wp_checkbox(
		array(
			'id'          => '_perfectpixel_product_fee',
			'label'       => 'Επιπλέον χρέωση',
			'description' => 'Προσθέτει «{{product_fee_label}}» ({{product_fee_percent}}%) στο καλάθι',
		)
	);
	echo '</div>';
}

function perfectpixel_product_fee_save( $product ) {
	$product->update_meta_data( '_perfectpixel_product_fee', isset( $_POST['_perfectpixel_product_fee'] ) ? 'yes' : 'no' );
}

function perfectpixel_product_fee_apply( $cart ) {
	if ( is_admin() && ! wp_doing_ajax() ) {
		return;
	}
	$base = 0.0;
	foreach ( $cart->get_cart() as $item ) {
		$product = wc_get_product( $item['product_id'] ); // Parent for variations.
		if ( $product && 'yes' === $product->get_meta( '_perfectpixel_product_fee' ) ) {
			$base += (float) $item['line_total'];
		}
	}
	$fee = $base * (float) '{{product_fee_percent}}' / 100;
	if ( $fee > 0 ) {
		$cart->add_fee( '{{product_fee_label}}', round( $fee, wc_get_price_decimals() ), 'yes' === '{{product_fee_taxable}}' );
	}
}
